import{c as t,Q as r,j as e,m as o}from"./chunks/framework.BPKcPtvA.js";const i="/screenshots/settings.png",l="/screenshots/card-category-popup.png",h="/screenshots/settings-stats.png",O=JSON.parse('{"title":"設定画面","description":"","frontmatter":{},"headers":[],"relativePath":"guide/settings.md","filePath":"guide/settings.md","lastUpdated":1786391114000}'),n={name:"guide/settings.md"};function s(d,a,p,c,u,g){return r(),e("div",null,[...a[0]||(a[0]=[o('<h1 id="設定画面" tabindex="-1">設定画面 <a class="header-anchor" href="#設定画面" aria-label="Permalink to &quot;設定画面&quot;">​</a></h1><p>画面左端の歯車アイコン「設定」から開きます (メインタブを上部表示に変えた場合は 上部の「設定」タブです)。 全項目は即時保存されます (変更した瞬間に保存)。</p><p><img src="'+i+'" alt="設定画面 — 即時保存される各種の切り替え / スライダー"></p><h2 id="起動時に自動で行うこと" tabindex="-1">起動時に自動で行うこと <a class="header-anchor" href="#起動時に自動で行うこと" aria-label="Permalink to &quot;起動時に自動で行うこと&quot;">​</a></h2><p>アプリを起動すると、まず<strong>通知ベルに届くだけの軽い確認</strong>がすぐに走り、そのあと <strong>BOOTH からのデータ取得</strong>が画面表示の落ち着いたあとに順番に走ります。 <strong>前回から十分に時間が経っていないものは飛ばす</strong>ので、毎回すべてを実行するわけ ではありません。各処理は対応する設定で ON/OFF や間隔を変えられます。</p><h3 id="すぐに確認するもの-通知ベルに届くだけ・画面の操作を妨げません" tabindex="-1">すぐに確認するもの (通知ベルに届くだけ・画面の操作を妨げません) <a class="header-anchor" href="#すぐに確認するもの-通知ベルに届くだけ・画面の操作を妨げません" aria-label="Permalink to &quot;すぐに確認するもの (通知ベルに届くだけ・画面の操作を妨げません)&quot;">​</a></h3><ul><li><strong>アップデートの確認</strong> (GitHub) — <a href="#アップデート">起動時にアップデートを確認する</a>が ON で、前回から 24 時間以上経っているとき。</li><li><strong>お知らせの取り込み</strong> — 運営からのお知らせを通知ベルに取り込みます。</li><li><strong>フォロー新着商品の確認</strong> — <a href="#フォロー中ショップの新着チェック間隔">フォロー中ショップの新着チェック間隔</a>で 間引きます。新しく出た商品を通知ベルでお知らせします (ライブラリの自動取得が OFF でも動きます)。</li></ul><h3 id="そのあと順番に行うもの-booth-からのデータ取得" tabindex="-1">そのあと順番に行うもの (BOOTH からのデータ取得) <a class="header-anchor" href="#そのあと順番に行うもの-booth-からのデータ取得" aria-label="Permalink to &quot;そのあと順番に行うもの (BOOTH からのデータ取得)&quot;">​</a></h3><ol><li><strong>中断したダウンロードの再開</strong> — 前回終了時に途中だったダウンロードを続きから再開します。</li><li><strong>ライブラリの自動取得</strong> — <a href="#起動時にライブラリを自動取得する">起動時にライブラリを自動取得する</a>が ON のときだけ。次の順に行います: <ol><li>新しく購入したアイテムの取り込み</li><li>購入日の補完 (注文履歴の確認)</li><li>すでにあるアイテムの商品情報の更新 (古いものから順に)</li></ol></li><li><strong>フォロー中ショップ一覧の更新</strong> — フォローの増減や名前・アイコンを最新化します (<a href="#フォロー中ショップの新着チェック間隔">フォロー中ショップの新着チェック間隔</a>で間引き、 初回起動時はまとめて取り込み)。</li><li><strong>スキリストの同期</strong> — リストや所属の同期は 24 時間ごと、商品情報と値下げの 確認は設定した間隔で行います (こちらもライブラリの自動取得とは別に動きます)。</li></ol><p>ダウンロードと、ライブラリ・ショップ・スキリストの BOOTH データ取得中は、 <a href="/guide/background-tasks#どこから確認する">バックグラウンドタスク</a> で現在の手順と 進み具合を確認し、中止できます。アップデート・お知らせ・フォロー新着の軽い確認は 通知ベルへ結果だけが届き、バックグラウンドタスクには表示されません。</p><h2 id="booth-との通信" tabindex="-1">BOOTH との通信 <a class="header-anchor" href="#booth-との通信" aria-label="Permalink to &quot;BOOTH との通信&quot;">​</a></h2><h3 id="起動時にライブラリを自動取得する" tabindex="-1">起動時にライブラリを自動取得する <a class="header-anchor" href="#起動時にライブラリを自動取得する" aria-label="Permalink to &quot;起動時にライブラリを自動取得する&quot;">​</a></h3><p>(デフォルト ON)</p><p>OFF にすると、起動時の<strong>ライブラリの自動取得</strong>を行いません (手動でのライブラリ更新、URL・ファイルの追加、ダウンロードは引き続き利用できます)。 フォロー中ショップ・スキリストの自動確認はこれとは別で、それぞれの間隔で動きます (→ <a href="#起動時に自動で行うこと">起動時に自動で行うこと</a>)。</p><h3 id="ページ取得間隔" tabindex="-1">ページ取得間隔 <a class="header-anchor" href="#ページ取得間隔" aria-label="Permalink to &quot;ページ取得間隔&quot;">​</a></h3><p>(デフォルト 1 秒、0.1 秒〜5 秒)</p><p>BOOTH からデータを取得するとき (ライブラリスキャン・スキリストやショップの確認・ 商品情報の再取得など)、<strong>1 回ごとに挟む待機時間</strong>。短いほど速く、長いほど BOOTH 側の 負荷が軽くなります。ここ 1 つで、アプリが BOOTH にアクセスする間隔をまとめて調整できます。</p><h3 id="フォロー中ショップの新着チェック間隔" tabindex="-1">フォロー中ショップの新着チェック間隔 <a class="header-anchor" href="#フォロー中ショップの新着チェック間隔" aria-label="Permalink to &quot;フォロー中ショップの新着チェック間隔&quot;">​</a></h3><p>(デフォルト 24 時間、1〜168 時間 = 7 日)</p><p>起動時に、最後の確認からこの時間以上経っていれば、フォロー中ショップの一覧と 新着商品をまとめて確認します。新しく出た商品は通知ベルでお知らせします。 短いほど早く気付けますが、BOOTH 側の負荷も上がります。</p><h3 id="スキリスト値下げチェック間隔" tabindex="-1">スキリスト値下げチェック間隔 <a class="header-anchor" href="#スキリスト値下げチェック間隔" aria-label="Permalink to &quot;スキリスト値下げチェック間隔&quot;">​</a></h3><p>(デフォルト 24 時間、1〜168 時間 = 7 日)</p><p>起動時に、最後の確認からこの時間以上経ったスキリストの商品を 1 件ずつ確認し、 値下げがあれば通知ベルと、カードの「↓ N%」表示でお知らせします。 短いほど早く気付けますが、BOOTH 側の負荷も上がります。</p><h3 id="ライブラリ商品情報の再取得間隔" tabindex="-1">ライブラリ商品情報の再取得間隔 <a class="header-anchor" href="#ライブラリ商品情報の再取得間隔" aria-label="Permalink to &quot;ライブラリ商品情報の再取得間隔&quot;">​</a></h3><p>(デフォルト 24 時間、1〜168 時間 = 7 日)</p><p>起動時のライブラリ取得のあと、最後に商品情報を取得してからこの時間以上経った アイテムを、古いものから順に取り直して商品名・価格・タグなどを最新にします。 短いほど情報は新しく保たれますが、BOOTH 側の負荷も上がります。</p><h2 id="保存場所" tabindex="-1">保存場所 <a class="header-anchor" href="#保存場所" aria-label="Permalink to &quot;保存場所&quot;">​</a></h2><h3 id="ダウンロード先フォルダ" tabindex="-1">ダウンロード先フォルダ <a class="header-anchor" href="#ダウンロード先フォルダ" aria-label="Permalink to &quot;ダウンロード先フォルダ&quot;">​</a></h3><p>新しくダウンロードするファイルの保存先。 既存ファイルは元の場所に残ったままで、ライブラリは前のパスも認識し続けます (= 移動先を変えても過去のものは消えない)。</p><h3 id="zip-保管モード" tabindex="-1">ZIP 保管モード <a class="header-anchor" href="#zip-保管モード" aria-label="Permalink to &quot;ZIP 保管モード&quot;">​</a></h3><p>(デフォルト OFF)</p><p>ON にすると、ダウンロードした <code>.zip</code> を自動展開せず ZIP のまま保管します。</p><ul><li>ON 推奨ケース: 自前で 7-Zip などで管理したい / 元の zip を保ちたい</li><li>OFF (デフォルト): zip は受信後すぐ展開され、保存先のパスは展開先フォルダを指す</li></ul><p>この切り替えは <strong>新しいダウンロードにだけ</strong> 効きます (= 既存の展開済みアイテムはそのまま)。</p><h3 id="追加した商品をすぐダウンロード" tabindex="-1">追加した商品をすぐダウンロード <a class="header-anchor" href="#追加した商品をすぐダウンロード" aria-label="Permalink to &quot;追加した商品をすぐダウンロード&quot;">​</a></h3><p>(デフォルト ON)</p><p>手動の「BOOTH URL から追加」と、ブラウザの「BOOTH Library Manager で DL」リンクで 追加したファイルを、登録と同時に自動でダウンロードします。 OFF にすると登録だけ行い、あとから各ファイルのダウンロードボタンで個別に開始できます。</p><p>起動時のライブラリ取得 (購入・ギフトのスキャン) はこの設定に関係なく、 今までどおり登録のみです。</p><h3 id="無料ダウンロードの新着も自動でダウンロード" tabindex="-1">無料ダウンロードの新着も自動でダウンロード <a class="header-anchor" href="#無料ダウンロードの新着も自動でダウンロード" aria-label="Permalink to &quot;無料ダウンロードの新着も自動でダウンロード&quot;">​</a></h3><p>(デフォルト OFF)</p><p>ON にすると、無料ダウンロード履歴のスキャンで新しく見つかった商品のファイルも 自動でダウンロードします。使い始めの最初の取り込み分は対象にならないので、 ON にしていても導入直後に大量のダウンロードが始まることはありません。</p><h2 id="表示" tabindex="-1">表示 <a class="header-anchor" href="#表示" aria-label="Permalink to &quot;表示&quot;">​</a></h2><h3 id="カードにカーソルを乗せてカテゴリ一覧をポップアップ" tabindex="-1">カードにカーソルを乗せてカテゴリ一覧をポップアップ <a class="header-anchor" href="#カードにカーソルを乗せてカテゴリ一覧をポップアップ" aria-label="Permalink to &quot;カードにカーソルを乗せてカテゴリ一覧をポップアップ&quot;">​</a></h3><p>(デフォルト ON)</p><p>カード上の情報行 (カテゴリタグ群) にカーソルを乗せると、付いている全カテゴリ (BOOTH 親 / 子 + カスタム + メモ) をポップアップで表示します。</p><p><img src="'+l+'" alt="カードにカーソルを乗せたときのカテゴリポップアップ — BOOTH 親 / 子・カスタム・メモ をまとめて表示"></p><p>「邪魔だ」と感じる場合は OFF。</p><h3 id="画像の拡大プレビュー" tabindex="-1">画像の拡大プレビュー <a class="header-anchor" href="#画像の拡大プレビュー" aria-label="Permalink to &quot;画像の拡大プレビュー&quot;">​</a></h3><p>(デフォルト ON)</p><p>サムネイルにカーソルを約 0.6 秒乗せると、拡大した画像をポップアップ表示します。 サムネイルを右クリック →「画像を拡大表示」で画面いっぱいに表示できます (この設定に 関係なくいつでも使えます)。</p><h3 id="グループ表示で選べる軸" tabindex="-1">グループ表示で選べる軸 <a class="header-anchor" href="#グループ表示で選べる軸" aria-label="Permalink to &quot;グループ表示で選べる軸&quot;">​</a></h3><p>(デフォルト: ショップ / BOOTH カテゴリ / カスタムカテゴリ / タグ / スキリスト / 取得元)</p><p>ライブラリの <a href="/guide/library#グループ表示">▦ グループ表示</a> のボタンを押したときに 選択肢として出す軸を、ドロップダウンから選びます。「あり / なし」の 2 つに 分かれるだけの軸 (お気に入り・最近開いた・更新あり・アーカイブ・ゴミ箱・ 非公開・販売終了・R-18) は、はじめは表示しない設定になっています — 使いたいものだけ チェックを入れてください。</p><p>使用中の軸のチェックを外すと、そのときのグループ表示は「グループ化なし」に戻ります。</p><h3 id="詳細画面のファイル一覧の並び順" tabindex="-1">詳細画面のファイル一覧の並び順 <a class="header-anchor" href="#詳細画面のファイル一覧の並び順" aria-label="Permalink to &quot;詳細画面のファイル一覧の並び順&quot;">​</a></h3><p>(デフォルト「現行版を上に」)</p><p><a href="/guide/library-detail">商品詳細画面</a> のファイル一覧の並び順を 3 択から選びます。</p><ul><li><strong>現行版を上に</strong>: 各バージョン系列の現行版を上、旧版を下に集めて、それぞれの中で名前の昇順 (v1, v2, v10 が正しく並ぶ自然順)</li><li><strong>名前順</strong>: 現行 / 旧の区別をなくした単純な名前の昇順</li><li><strong>取得時の順序</strong>: 保存されているファイル一覧の並びをそのまま使用</li></ul><h3 id="ライブラリの-r-18-表示をスキリストにも反映" tabindex="-1">ライブラリの R-18 表示をスキリストにも反映 <a class="header-anchor" href="#ライブラリの-r-18-表示をスキリストにも反映" aria-label="Permalink to &quot;ライブラリの R-18 表示をスキリストにも反映&quot;">​</a></h3><p>(デフォルト ON)</p><p>ON のとき、ライブラリ画面の「R-18 商品を表示」の切り替えがスキリスト側にも 自動で同期します。OFF にするとスキリスト側は独自の「R-18 を表示」の切り替えが効きます (両者完全独立)。</p><h3 id="旧バージョンをファイル数・一括ダウンロードに含めない" tabindex="-1">旧バージョンをファイル数・一括ダウンロードに含めない <a class="header-anchor" href="#旧バージョンをファイル数・一括ダウンロードに含めない" aria-label="Permalink to &quot;旧バージョンをファイル数・一括ダウンロードに含めない&quot;">​</a></h3><p>(デフォルト ON)</p><p>同じファイルの版違い (v1 / v2 …) があるとき、カードのファイル数表示と 「全てダウンロード」「複数選択ダウンロード」の対象を<strong>現行版のみ</strong>にします。 旧版はデータとして残り、<a href="/guide/library-detail">商品詳細画面</a> から個別に ダウンロードできます。</p><p>OFF にすると、ファイル数も一括ダウンロードも全バージョンを対象にします。 切り替えると全カードのファイル数表示が即座に再計算されます。</p><h2 id="ライセンス" tabindex="-1">ライセンス <a class="header-anchor" href="#ライセンス" aria-label="Permalink to &quot;ライセンス&quot;">​</a></h2><h3 id="状態" tabindex="-1">状態 <a class="header-anchor" href="#状態" aria-label="Permalink to &quot;状態&quot;">​</a></h3><p>認証済みライセンスキーの一部、認証日、サーバーへ最後に確認できた時刻を表示します。</p><h3 id="ログアウト" tabindex="-1">ログアウト <a class="header-anchor" href="#ログアウト" aria-label="Permalink to &quot;ログアウト&quot;">​</a></h3><p>ライセンス情報を手元から削除して認証画面に戻ります。 通常ライセンスが有効な間だけボタンが出ます。 認証画面に戻ったあとは、ライセンスキーの入力か、<strong>「BOOTH アカウントで認証」</strong> ボタン (このアプリを BOOTH で購入 / ギフト受け取り済みの場合) で、もう一度認証できます。 この操作だけでは、サーバーに登録済みの端末枠は解除されません。</p><h3 id="オンライン確認について" tabindex="-1">オンライン確認について <a class="header-anchor" href="#オンライン確認について" aria-label="Permalink to &quot;オンライン確認について&quot;">​</a></h3><p>起動のたびに、ライセンスが有効かどうかをサーバーへ確認します。 ネットワークに接続できないときは、<strong>最後に確認できた日から 14 日間</strong>は オフラインのまま起動できます (オフライン耐性)。</p><p>14 日を超えてもオンライン確認ができていない場合は認証画面に戻ります。 ネットワークに接続した状態でアプリを再起動すれば、再確認が通って そのまま利用を続けられます (ライセンスキーの再入力は不要)。</p><div class="tip custom-block"><p class="custom-block-title">端末の時計について</p><p>オフライン猶予は端末の時計を基準に判定します。時計を大きく過去・未来に ずらしているとオンライン確認を求められることがあります。</p></div><h3 id="別の-pc-で使う場合" tabindex="-1">別の PC で使う場合 <a class="header-anchor" href="#別の-pc-で使う場合" aria-label="Permalink to &quot;別の PC で使う場合&quot;">​</a></h3><p>ライセンスは <strong>アクティベートした PC に紐づきます</strong>。 <code>license.json</code> を別の PC にコピーしても、その PC では起動時に弾かれ (「このマシンでは認証できないライセンスです」)、認証画面に戻ります。</p><p>別の PC で使いたいときは、その PC でライセンスキーを入力して アクティベートしてください (利用できる台数の上限内であれば登録できます)。 OS の再インストールや PC 名の変更をした場合も、同じ PC でもう一度 アクティベートが必要になることがあります。</p><h2 id="booth-ログイン" tabindex="-1">BOOTH ログイン <a class="header-anchor" href="#booth-ログイン" aria-label="Permalink to &quot;BOOTH ログイン&quot;">​</a></h2><p>この節は、<strong>アプリの中で BOOTH にログイン済みのときだけ</strong> 表示されます (ログインしていないときは出ません)。アプリ内でのログインのしかたは <a href="/guide/installation#booth-ログイン">BOOTH ログイン</a> を参照してください。</p><h3 id="booth-からログアウト" tabindex="-1">BOOTH からログアウト <a class="header-anchor" href="#booth-からログアウト" aria-label="Permalink to &quot;BOOTH からログアウト&quot;">​</a></h3><p>「🚪 BOOTH からログアウト」を押すと、<strong>このアプリの中の</strong> BOOTH ログインだけを 解除します。ブラウザ側のログインや、<a href="#ライセンス">ライセンス</a> には影響しません。 ライブラリの取得やライセンスの自動認証でアプリ内ログインが再び必要になったら、 もう一度ログインしてください。</p><h2 id="アップデート" tabindex="-1">アップデート <a class="header-anchor" href="#アップデート" aria-label="Permalink to &quot;アップデート&quot;">​</a></h2><h3 id="起動時にアップデートを確認する" tabindex="-1">起動時にアップデートを確認する <a class="header-anchor" href="#起動時にアップデートを確認する" aria-label="Permalink to &quot;起動時にアップデートを確認する&quot;">​</a></h3><p>(デフォルト ON)</p><p>ON のとき、24 時間以上経過していれば起動時に GitHub Releases を確認し、 新しいバージョンがあれば通知ベルに「📦 アップデートあり」を出します。 OFF にすると起動時には確認しません。必要なときは「今すぐ確認」で手動確認できます。</p><h3 id="アプリを閉じるときに自動で更新する" tabindex="-1">アプリを閉じるときに自動で更新する <a class="header-anchor" href="#アプリを閉じるときに自動で更新する" aria-label="Permalink to &quot;アプリを閉じるときに自動で更新する&quot;">​</a></h3><p>(デフォルト ON)</p><p>新しいバージョンが見つかったら、アプリを使っているあいだに裏で更新ファイルを ダウンロードしておき、次にアプリを閉じたタイミングで適用します。</p><ul><li>閉じてから通信が始まることはありません (ダウンロードは使用中に済ませます)。</li><li>更新のあとにアプリが<strong>起動し直すことはありません</strong>。次に自分で起動したときが 新しいバージョンになります。</li><li>ダウンロードや更新に失敗しても操作の邪魔はしません。次にアップデートを確認した タイミング (既定では 24 時間後の起動時、または「今すぐ確認」) でまた試します。</li><li>上の「起動時にアップデートを確認する」が OFF のあいだは、自動更新も行いません。 「今すぐ確認」で見つけた更新は、通知ベルから手動で適用できます。</li><li>OFF にすると、既にダウンロード済みの更新も破棄します。通知ベルの 「📦 アップデートあり」からは手動で更新できます (手動更新では、適用後にアプリが起動し直します)。</li><li>更新の確認ダイアログで<strong>キャンセルしたバージョンは、閉じるときにも適用しません</strong>。 そのあとさらに新しいバージョンが出たら、また対象になります。</li><li>閉じた直後にすぐアプリを開き直した場合は、更新を諦めます (動いているアプリを 書き換えないため)。改めて適用されるのは、次にアップデートを確認したとき (既定では 24 時間後の起動時、または「今すぐ確認」) です。</li><li>更新の適用に失敗した場合 (書き込みできない場所にインストールされているなど)、 そのバージョンの自動ダウンロードは止めます。同じファイルを何度も落とし直さない ためです。通知ベルからは手動で更新できます。</li><li>Windows のシャットダウン / サインアウトで閉じたときは適用しません (書き換えの途中で中断されるのを避けるため)。次の通常終了時に適用します。</li></ul><h3 id="確認間隔" tabindex="-1">確認間隔 <a class="header-anchor" href="#確認間隔" aria-label="Permalink to &quot;確認間隔&quot;">​</a></h3><p>(デフォルト 24 時間、0〜168 時間 = 7 日)</p><p>上の確認を、前回から何時間経ったらもう一度行うかを決めます。 <strong>0 にすると起動のたび</strong>に確認します。起動中に定期的な確認は行いません。</p><h3 id="今すぐ確認" tabindex="-1">今すぐ確認 <a class="header-anchor" href="#今すぐ確認" aria-label="Permalink to &quot;今すぐ確認&quot;">​</a></h3><p>現在のバージョンと最新リリースを比較表示し、「今すぐ確認」ボタンで即時に再チェックできます。</p><h3 id="アップデートの適用" tabindex="-1">アップデートの適用 <a class="header-anchor" href="#アップデートの適用" aria-label="Permalink to &quot;アップデートの適用&quot;">​</a></h3><p>新しいバージョンが見つかると通知ベルに「📦 アップデートあり」が出ます。 これをクリックすると、確認ダイアログのあと <strong>アプリ内で自動的に更新</strong> します (ダウンロード → 置き換え → 再起動まで自動)。インストーラ版・ポータブル版に 対応します。ZIP 版は安全な自動置換ができないため、GitHub のリリースページを ブラウザで開いて手動更新を案内します。</p><h2 id="キャッシュ" tabindex="-1">キャッシュ <a class="header-anchor" href="#キャッシュ" aria-label="Permalink to &quot;キャッシュ&quot;">​</a></h2><h3 id="画像キャッシュ-商品サムネ・ショップアイコン" tabindex="-1">画像キャッシュ (商品サムネ・ショップアイコン) <a class="header-anchor" href="#画像キャッシュ-商品サムネ・ショップアイコン" aria-label="Permalink to &quot;画像キャッシュ (商品サムネ・ショップアイコン)&quot;">​</a></h3><p>BOOTH から取得した画像を手元に保存しています。現在の使用量が表示され、 「キャッシュをクリア」で削除できます。クリアしても次回アクセス時に自動で 再取得されるので、ディスク容量を空けたいときだけ実行すれば大丈夫です。</p><h3 id="ログの削除" tabindex="-1">ログの削除 <a class="header-anchor" href="#ログの削除" aria-label="Permalink to &quot;ログの削除&quot;">​</a></h3><p>画像とは別に、アプリの動作の記録 (ログ) も少しずつ溜まります。現在の使用量が 表示され、「ログを削除」で消して空き容量を増やせます。不具合を調べるときに 使う記録なので、普段は気にしなくて大丈夫です。今使用中の分は残ります。</p><h2 id="ストレージ最適化と重複表示" tabindex="-1">ストレージ最適化と重複表示 <a class="header-anchor" href="#ストレージ最適化と重複表示" aria-label="Permalink to &quot;ストレージ最適化と重複表示&quot;">​</a></h2><h3 id="完全重複・旧バージョンの整理" tabindex="-1">完全重複・旧バージョンの整理 <a class="header-anchor" href="#完全重複・旧バージョンの整理" aria-label="Permalink to &quot;完全重複・旧バージョンの整理&quot;">​</a></h3><p>「ストレージを解析」を押すと、アプリの管理フォルダにあるダウンロード済みの ファイルと展開済みフォルダを調べ、削除できる候補を表示します。</p><ul><li><strong>完全一致</strong>: 中身が同じものをまとめ、各グループで 1 件を必ず保持します。 削除候補は最初から選択されています。</li><li><strong>旧版</strong>: ファイル名の版番号から現行版と判断できないものです。誤削除を防ぐため 最初は選択されていません。「旧版」と「旧版（再取得不可）」の Foldout ごとに 「すべて削除対象」でまとめて選択できます。</li></ul><p>候補の各行には「商品名 / ファイル名」とサイズが表示されます。「商品名 / ファイル名」 を押すと、該当ファイルを選択した状態でその商品の詳細画面を開けます。 配布終了などで再ダウンロードできない旧版は、専用の Foldout に分けて表示されます。</p><p>削除したファイルはライブラリから消えず、「未取得」に戻ります。BOOTH で引き続き 提供されていれば再ダウンロードできます。「再取得不可」の旧版は、削除すると復元も 再ダウンロードもできません。警告を確認して選択した場合だけ削除されます。 ローカル取り込み、アーカイブ・ゴミ箱内、ダウンロード処理中のデータは削除候補に なりません。実行直前にもファイルとライブラリの状態を確認し、解析後に変化した候補は スキップします。</p><h3 id="重複ファイルのスキャン" tabindex="-1">重複ファイルのスキャン <a class="header-anchor" href="#重複ファイルのスキャン" aria-label="Permalink to &quot;重複ファイルのスキャン&quot;">​</a></h3><p>「重複をスキャン」を押すと、ダウンロード済みファイル (ZIP は展開後のフォルダ 全体) の中身から一意の値を計算して保存します。同じ中身のファイルが 2 つ以上あると、 <a href="/guide/library-detail">商品詳細画面</a> の各ファイル情報に <strong>「🔁 同一ファイル N 件」</strong> リンクが出て、重複を一覧・相互に移動できます。</p><ul><li>複数アイテムにまたがる重複も洗い出せます</li><li>大きなファイルが多いと時間がかかります (「キャンセル」で中断可能)</li><li>進捗・残り件数はボタン横に表示されます</li></ul><h2 id="エクスポート-インポート" tabindex="-1">エクスポート / インポート <a class="header-anchor" href="#エクスポート-インポート" aria-label="Permalink to &quot;エクスポート / インポート&quot;">​</a></h2><h3 id="バックアップの書き出し-読み込み" tabindex="-1">バックアップの書き出し / 読み込み <a class="header-anchor" href="#バックアップの書き出し-読み込み" aria-label="Permalink to &quot;バックアップの書き出し / 読み込み&quot;">​</a></h3><p>次のデータを <strong>1 つの JSON ファイル</strong> にまとめてエクスポートできます。 バックアップや、別の PC への移行に使えます。</p><ul><li>ライブラリ、カスタムカテゴリ、設定、アイテムのメモ、手動追加アイテムに設定したサムネイル画像</li><li>スキリスト、フォロー中ショップ、販売開始通知のスケジュール、新着商品の確認状況</li></ul><p>手動追加アイテムに設定したサムネイル画像は 1 枚 30 MiB まで含められます。上限を超える画像が ある場合は、どの画像が対象かを表示してエクスポートを中止します。</p><p>通知履歴、ライセンス・認証情報、ログ、BOOTH から再取得できる画像キャッシュ、ダウンロード済みファイル、 アーカイブ ZIP、ダウンロード先フォルダのパスは含まれません。お気に入りや絞り込み プリセットなどの画面設定も対象外です。</p><p>読み込んだライブラリで BOOTH から再取得できるファイルは「未取得」状態になります。 ローカルから追加したファイル本体は含まれず、該当行は「情報のみ」として残ります。 移行先ですでに設定しているダウンロード先フォルダは変更しません。</p><ul><li><strong>エクスポート</strong>: 保存先を選んで JSON をエクスポートする</li><li><strong>インポート</strong>: 選んだ JSON に含まれるデータを現在のデータへ上書きし、 完了後にアプリを自動で再起動する</li></ul><p>旧形式のバックアップも読み込めます。旧形式に含まれていない種類のデータは、 現在の内容をそのまま残します。</p><blockquote><p>ライセンスはエクスポート対象に含まれません。別の PC では改めてアクティベートが 必要です (<a href="#ライセンス">ライセンス</a>)。</p></blockquote><h2 id="ゴミ箱" tabindex="-1">ゴミ箱 <a class="header-anchor" href="#ゴミ箱" aria-label="Permalink to &quot;ゴミ箱&quot;">​</a></h2><h3 id="ゴミ箱の管理" tabindex="-1">ゴミ箱の管理 <a class="header-anchor" href="#ゴミ箱の管理" aria-label="Permalink to &quot;ゴミ箱の管理&quot;">​</a></h3><p>ゴミ箱に入れたアイテムは <strong>30 日経過後に自動で完全削除</strong> されます。 現在の件数が表示され、ここから一括操作できます:</p><ul><li><strong>すべて復元</strong>: ゴミ箱の全アイテムをライブラリに戻す</li><li><strong>ゴミ箱を空にする</strong>: 全アイテムを今すぐ完全削除する</li></ul><p>完全削除ではライブラリの登録情報とダウンロード済みファイルを削除します。 アイテムのメモとカテゴリ設定は残ります。</p><p>個別の復元は、ライブラリの「表示オプション」→「🗑️ ゴミ箱を表示」で ゴミ箱のカードを出して、右クリックメニューから行います。</p><h2 id="キーボードショートカット" tabindex="-1">キーボードショートカット <a class="header-anchor" href="#キーボードショートカット" aria-label="Permalink to &quot;キーボードショートカット&quot;">​</a></h2><h3 id="ショートカットの変更" tabindex="-1">ショートカットの変更 <a class="header-anchor" href="#ショートカットの変更" aria-label="Permalink to &quot;ショートカットの変更&quot;">​</a></h3><p>「ショートカットの変更」の一覧で、各コマンドの行をクリックして新しいキー操作 / マウス操作を押すと<strong>割り当て直し</strong>できます。</p><ul><li><strong>Esc</strong>: 割り当て直しをキャンセル</li><li><strong>↺ ボタン</strong>: そのコマンドをデフォルトのキーに戻す</li><li>方向キーによるカード移動を含め、一覧内の各コマンドを割り当て直せます</li><li>既に使われているキーには割り当てできません (警告が出ます)</li></ul><h3 id="ショートカット一覧" tabindex="-1">ショートカット一覧 <a class="header-anchor" href="#ショートカット一覧" aria-label="Permalink to &quot;ショートカット一覧&quot;">​</a></h3><p>「一覧を表示」(折りたたみ) で、画面・用途ごとに分けた現在の割り当てと、 主な固定操作を確認できます。</p><p>詳細は <a href="/guide/keyboard-shortcuts">キーボードショートカット</a> も参照。</p><h2 id="外部との通信" tabindex="-1">外部との通信 <a class="header-anchor" href="#外部との通信" aria-label="Permalink to &quot;外部との通信&quot;">​</a></h2><p>このアプリがインターネットに接続する先と、そのとき何を送るかの一覧です。 主な接続先は次の通りです。</p><table tabindex="0"><thead><tr><th>接続先</th><th>いつ</th><th>送るもの</th></tr></thead><tbody><tr><td><strong>BOOTH</strong> (booth.pm)</td><td>ライブラリの取得 / スキリストの同期 / 価格チェック / ファイルのダウンロード / 商品画像の取得</td><td>ブラウザまたはアプリ内の BOOTH ログイン状態、商品 ID</td></tr><tr><td><strong>GitHub</strong> (api.github.com)</td><td>起動時または「今すぐ確認」のアップデート確認、更新ファイルのダウンロード</td><td>アプリ名とバージョン (User-Agent)。個人データは送信しません</td></tr><tr><td><strong>ライセンス確認サーバー</strong></td><td>アクティベート、有効性チェック、運営からのお知らせ取得</td><td>ライセンスキー、この PC を識別する情報、PC 名、アプリのバージョン。BOOTH アカウント認証時は、対象商品の注文番号またはギフト識別子、商品 ID、購入確認結果も送信</td></tr><tr><td><strong>価格データ取得サーバー</strong></td><td>スキリストで<a href="/guide/wishlist#価格の推移">「価格の推移」</a>を開いたとき</td><td>表示中の商品 ID のみ</td></tr></tbody></table><ul><li><strong>BOOTH</strong> へのアクセスは、あなたが自分のブラウザで BOOTH を見るのと同じ範囲です (自分の購入履歴・スキリストを読むためにログイン情報を使います)。</li><li><strong>GitHub</strong> への通信は「アップデート」の設定で OFF にできます。OFF にすると 起動時の自動確認を行いません。手動で確認や更新を行った場合は GitHub と通信します。</li><li><strong>価格データ取得サーバー</strong> は、公開データセット <a href="https://mametarogg.github.io/" target="_blank" rel="noreferrer">Boopa</a> を 中継・キャッシュするためのものです。価格の記録をこちらから送ることはありません。</li></ul><p>同期・取得・更新処理の HTTP 通信は、設定の下部にある 「<a href="#受信ログ-ログ-デバッグ情報">ログ</a>」で確認できます。</p><h2 id="ライブラリ統計" tabindex="-1">ライブラリ統計 <a class="header-anchor" href="#ライブラリ統計" aria-label="Permalink to &quot;ライブラリ統計&quot;">​</a></h2><p>「📊 統計ダッシュボード」の「統計を表示」を開くと、開いた時点のライブラリを 集計して表示します (リアルタイム更新ではなく、開くたびに再集計)。</p><p><img src="'+h+'" alt="ライブラリ統計ダッシュボード — まとめカードとショップ別 / カテゴリ別の内訳"></p><ul><li><strong>アイテム / ダウンロード済み容量 / ファイル / ダウンロード完了 / ショップ / ギフト / 無料DL</strong> のまとめ</li><li><strong>アーカイブ / 更新あり / R-18 / 情報のみ / ゴミ箱</strong> の件数 (該当があるときのみ)</li><li><strong>ショップ別</strong> の内訳 (アイテム数、ダウンロード済み容量) — 上位 12 件</li><li><strong>カテゴリ別</strong> の内訳 (アイテム数) — 上位 12 件</li></ul><h2 id="ライブラリ" tabindex="-1">ライブラリ <a class="header-anchor" href="#ライブラリ" aria-label="Permalink to &quot;ライブラリ&quot;">​</a></h2><h3 id="全ファイル削除" tabindex="-1">全ファイル削除 <a class="header-anchor" href="#全ファイル削除" aria-label="Permalink to &quot;全ファイル削除&quot;">​</a></h3><p>「ダウンロード済みファイルの一括削除」ボタンから:</p><ul><li><strong>デフォルト</strong>: ディスク上のファイルだけ削除し、商品リストの項目は「未取得」状態に戻します。ローカルから追加したファイルや配布終了したファイルは再取得できない場合があります</li><li><strong>チェックボックス ON</strong>: 商品・ファイル一覧も削除します。購入履歴などから再取得するまでライブラリから消えます</li></ul><h2 id="受信ログ-ログ-デバッグ情報" tabindex="-1">受信ログ / ログ / デバッグ情報 <a class="header-anchor" href="#受信ログ-ログ-デバッグ情報" aria-label="Permalink to &quot;受信ログ / ログ / デバッグ情報&quot;">​</a></h2><p>画面の一番下に、3 つの折りたたみがあります:</p><ul><li><strong>受信ログ</strong>: ブラウザの「BOOTH Library Manager で DL」を押したときに、アプリが受け取った内容の一覧です。「消去」で消せます</li><li><strong>ログ</strong>: BOOTH との HTTP 通信を中心とした記録 (パス / 状態 / 時刻 / 所要時間 / サイズ)。絞り込み検索ができ、「ファイル」ボタンでログのファイルをそのまま開けます。「消去」で消せます。ファイルはアプリのデータフォルダ内 <code>http-logs/</code> に保存されます</li><li><strong>デバッグ情報</strong>: プロトコル登録状態、ライブラリの商品数・ファイル数・完了ファイル容量、ダウンロード先、受信件数、アプリと実行環境のバージョン</li></ul><h2 id="初期設定に戻す" tabindex="-1">初期設定に戻す <a class="header-anchor" href="#初期設定に戻す" aria-label="Permalink to &quot;初期設定に戻す&quot;">​</a></h2><p>設定画面 最下部の「初期設定に戻す」ボタンで <code>settings.json</code> を初期値で書き直します。 保存先や表示、通信間隔などのアプリ設定へ即時反映されます。 ライブラリ、メモ、ログ、キャッシュ、ライセンスには影響しません。</p><h2 id="ファイル保存先" tabindex="-1">ファイル保存先 <a class="header-anchor" href="#ファイル保存先" aria-label="Permalink to &quot;ファイル保存先&quot;">​</a></h2><table tabindex="0"><thead><tr><th>ファイル</th><th>場所</th></tr></thead><tbody><tr><td><code>settings.json</code></td><td><code>%APPDATA%\\BOOTH Package Linker\\</code></td></tr><tr><td><code>library.json</code> / <code>library-item-media.json</code> 等 各データ</td><td><code>%APPDATA%\\BOOTH Package Linker\\</code></td></tr><tr><td>受信履歴 / アプリの動作ログ</td><td><code>%APPDATA%\\BOOTH Package Linker\\logs\\</code></td></tr><tr><td>HTTP 通信ログ</td><td><code>%APPDATA%\\BOOTH Package Linker\\http-logs\\</code></td></tr><tr><td>ダウンロードファイル</td><td>設定の「ダウンロード先フォルダ」 (デフォルト <code>&lt;Documents&gt;/booth-package-linker/</code>)</td></tr><tr><td>アーカイブ ZIP</td><td><code>%APPDATA%\\BOOTH Package Linker\\archive\\&lt;アイテムID&gt;.zip</code></td></tr></tbody></table>',153)])])}const q=t(n,[["render",s]]);export{O as __pageData,q as default};
